#include <stdio.h>

void swap_copy(int a, int b) { int t = a; a = b; b = t; }
void swap_ptr(int *a, int *b) { int t = *a; *a = *b; *b = t; }

int main(void) {
    int x = 1, y = 2;
    swap_copy(x, y);
    printf("%d %d\n", x, y);
    swap_ptr(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

